"""Build an offline review gallery from actual evidence; never invent a result."""
import json, math, re, html
from pathlib import Path
out = Path('docs/mission-25-evidence')
def read(name): return json.loads((out / name).read_text())
def esc(value): return html.escape(str(value))
def video(file, caption):
    assert (out / file).exists(), file
    return f'<figure><video controls playsinline preload="metadata" src="{esc(file)}"></video><figcaption>{esc(caption)} · <a href="{esc(file[:-5]+".json")}">trace</a></figcaption></figure>' if (out / (file[:-5]+'.json')).exists() else f'<figure><video controls playsinline preload="metadata" src="{esc(file)}"></video><figcaption>{esc(caption)}</figcaption></figure>'
parts = ['''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mission 25 — Le voyageur libre</title><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 16 16%22%3E%3Ccircle cx=%228%22 cy=%228%22 r=%227%22 fill=%22%233f664e%22/%3E%3C/svg%3E">
<style>:root{color-scheme:light;--ink:#233d32;--paper:#f3f0e7;--line:#d3d9cc}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.6 system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:36px 24px 80px}header{padding:28px 0 30px;border-bottom:1px solid var(--line)}h1{font:600 clamp(36px,5vw,64px)/1.1 Georgia,serif;margin:14px 0}h2{font:500 30px/1.2 Georgia,serif;margin:44px 0 16px}h3{font-size:17px;margin:24px 0 10px}.tag{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#78613a}.lede{max-width:820px;font-size:19px}.note{padding:16px 20px;background:#e6eadf;border-left:3px solid #637b5d}.grid,.pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}figure{margin:0;background:#fffdf8;border:1px solid var(--line);border-radius:9px;overflow:hidden}video,img{display:block;width:100%;max-width:100%;background:#263f35}figcaption{padding:10px 14px;font-size:13px}a{color:#42694e}nav{display:flex;gap:14px;flex-wrap:wrap;margin:24px 0}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}button{font:inherit;background:#fffdf8;border:1px solid #a3b39a;border-radius:5px;padding:7px 12px;cursor:pointer;min-height:44px}.table{overflow:auto}table{width:100%;border-collapse:collapse;background:#fffdf8;font-size:13px}th,td{padding:9px 12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{background:#e4e9db}.bad{color:#a24234}.small{font-size:13px;color:#607064}details{margin:16px 0}summary{cursor:pointer;font-weight:600}@media(max-width:650px){main{padding:20px 14px 60px}.grid,.pair{grid-template-columns:1fr}h2{font-size:26px}.lede{font-size:17px}th,td{padding:7px 9px}}</style>
<main><header><div class="tag">Endless Earth · Mission 25 · PR en brouillon</div><h1>Le voyageur libre</h1><p class="lede">Entrer dans l’Anglin, nager, mettre un packraft à l’eau et retrouver la berge. Les films ci-dessous montrent le jeu natif et ses limites.</p><p class="note"><b>Livraison partielle.</b> La profondeur est une approximation artistique pour le jeu, distincte d’un relevé réel. Ponts non ouverts, assise sur mobilier et franchissements détaillés restent à réaliser. La revue artistique et les mesures sur appareil physique restent ouvertes.</p><nav><a href="#eau">Anglin</a><a href="#bateau">Packraft</a><a href="#corps">Course avant/après</a><a href="#terrain">Pentes/escaliers</a><a href="#interactions">Interactions/son</a><a href="#mesures">Mesures</a><a href="#acceptation">Acceptation</a><a href="../mission-25.md">Rapport complet</a></nav></header>
<section><h2>Lire les preuves</h2><p>Films issus de MediaRecorder sur le canvas et, lorsque le son est activé, de l’AudioContext. Indexation WebM par copie de codecs : paquets vidéo et timestamps inchangés. Caméras, dates et placements de comparaison explicites. Aucune scène synthétique n’est présentée comme le pilote.</p><div class="toolbar"><span>Vitesse de visionnage :</span><button data-speed="1">1×</button><button data-speed="0.5">0,5×</button><button data-speed="0.25">0,25×</button><button id="pause">Tout mettre en pause</button></div><p class="small">Le ralenti agit uniquement sur la lecture des captures. Chromium / SwiftShader logiciel ; faible cadence conservée, aucune promesse de fluidité Android.</p></section>''']
water=read('runtime-checks.json')['water']
parts.append('<section id="eau"><h2>Trois berges de l’Anglin</h2><p>Marche, pataugeage, nage, demi-tour et sortie. Les profondeurs portent <code>source=estimated</code>, <code>confidence=low</code>. Aucun fond visible n’a été ajouté sous la surface opaque existante.</p><div class="grid">')
for i in range(1,4): parts.append(video(f'anglin-{i}.webm', f'Accès {i} — véritable polygone OSM de l’Anglin ; fond estimé'))
parts.append('</div><details><summary>Positions reproductibles et provenance</summary><div class="table"><table><tr><th>Accès</th><th>Position locale sèche (m)</th><th>Latitude / longitude dérivées</th><th>Source OSM</th></tr>')
for i,r in enumerate(water,1):
    a=r['site'];p=a['dry'];lat=46.6953-p['z']/111320;lon=.8844+p['x']/(111320*math.cos(math.radians(46.6953)))
    parts.append(f'<tr><td>{i} / {esc(a["id"])}</td><td>{p["x"]:.3f}, {p["y"]:.3f}, {p["z"]:.3f}</td><td>{lat:.6f}, {lon:.6f}</td><td>{esc(a["outline"])}</td></tr>')
parts.append('</table></div><p class="small">Coordonnées dérivées du repère local du jeu, pas relevés d’accès ni recommandations de baignade réelle. Tous les refus locaux ne sont pas filmés.</p></details></section><section id="bateau"><h2>Le packraft</h2>')
parts.append(video('packraft.webm','Sortie contextuelle → embarquement → navigation/virage/dérive → retour assisté explicite → rangement'))
parts.append('<p>Un objet réutilisé, quinze cycles automatisés sur le pilote. Pagaie originale, mains en IK, poussée liée aux phases de rame. Quatre appels de dessin actifs, 744 triangles. Le film couvre un court parcours ; pas de passage sous pont ni longue descente revendiqués. Dépliage et équipement restent stylisés.</p></section><section id="corps"><h2>La course : mêmes conditions, quatre angles</h2><p>La distance autorisée règle les pas. Durée d’appui/course, retour du genou, coordination du torse, bras et sac ont évolué. 19 os, un SkinnedMesh ; 3 072 triangles proches, 1 536 en Éco/au loin. Une réussite des tests ne remplace pas la revue de ces images.</p>')
for angle,label in [('rear','Arrière'),('profile','Profil'),('front','Face'),('three-quarter','Trois-quarts')]:
    parts.append(f'<h3>{label}</h3><div class="pair">'+video(f'before-run-{angle}.webm','Avant — main M24')+video(f'after-run-{angle}.webm','Après — M25')+'</div>')
parts.append('</section><section id="terrain"><h2>Axes de pente et d’escalier documentés</h2><p>Mêmes départs, commandes et supports. L’escalier est un axe OSM admis ; les contremarches individuelles ne sont pas relevées dans le MNT. Les films ne prouvent pas chaque obstacle du territoire.</p>')
for name,label in [('pente-marche-course','Pente / marche-course / arrêt / retour'),('escalier-documente','Escalier documenté / arrêt / retour')]:
    parts.append(f'<h3>{label}</h3><div class="pair">'+video(f'before-{name}.webm','Avant — M24')+video(f'after-{name}.webm','Après — M25')+'</div>')
parts.append('</section><section id="interactions"><h2>Sol, repos, petit saut et pluie</h2><div class="grid">')
for file,caption in [('ground-interactions.webm','Assise au sol confirmé, relèvement, petit saut et reprise de marche'),('rain-clothes.webm','Climat partagé : pluie, humidité et amorce de séchage ; séchage complet testé sans accélérer le film'),('ground-clear.webm','Contacts sur un substrat cartographié sec : traces et sons'),('ground-rain.webm','Même substrat sous pluie simulée : traces humides et sons'),('mobile-touch.webm','Émulation tactile 390×844 : joystick et actions du bateau ; placement diagnostique explicite entre scénarios'),('compiled-mobile-touch.webm','Bundle compilé : déplacement et regard par vrais événements tactiles CDP')]:
    parts.append(video(file,caption))
parts.append('</div><p>Assise sur banc/rocher, vault de tronc, flaques localisées, vraie flexion des brins d’herbe et effets vestimentaires fins restent ouverts. Les traces présentes sont des interprétations graphiques plafonnées, déclenchées par les contacts IK confirmés.</p><h2>Le crépitement du feu</h2>')
parts.append('<details><summary>Écouter le gain M24 avant calibration</summary>'+video('camp-audio-before.webm','Avant — chaîne M24 existante, mesurée trop faible depuis la caméra')+'</details>')
parts.append(video('camp-audio.webm','Sortie AudioContext native stéréo, dix cycles de camp et changements de profil'))
parts.append(video('camp-contemplation.webm','24 secondes de camp continu, sortie sonore réelle et passage par la reprise du fichier de 18 secondes, puis rangement'))
audio=read('audio.json')
parts.append(f'<p>Une voix de feu pendant chaque cycle, aucune après rangement. Enregistrement existant <i>Campfire.wav</i>, Defaultv, CC0-1.0, réutilisé. Sortie enregistrée : moyenne {audio["meanVolumeDb"]:.1f} dBFS, crête {audio["maxVolumeDb"]:.1f} dBFS. Ces niveaux portent sur le mix complet ; ils ne remplacent pas l’écoute. Casque, haut-parleurs et appareil physique non vérifiés.</p></section>')
perf=read('performance.json');active=read('active-performance.json');preserve=read('preservation.json')
parts.append('<section id="mesures"><h2>Mesures comparatives</h2><p>24 cas, trois profils ; échantillons chauds alternés, mêmes caméra/date/climat, rendu synchronisé par <code>gl.finish</code>. SwiftShader logiciel à 480×320. La CPU de contexte est incluse de façon conservatrice à chaque échantillon ; ce n’est pas un temps GPU physique ni une mesure de toute la simulation.</p><div class="table"><table><tr><th>Scène / profil</th><th>M24 médiane</th><th>M25 médiane</th><th>M25 P95</th><th>Écart</th><th>Appels</th><th>Triangles</th></tr>')
for r in perf['rows']:
    a,b=r['before'],r['after'];css=' class="bad"' if r['deltaPct']>5 else ''
    parts.append(f'<tr><td>{esc(r["scene"])} / {esc(r["profile"])}</td><td>{a["medianMs"]:.1f} ms</td><td>{b["medianMs"]:.1f} ms</td><td>{b["p95Ms"]:.1f} ms</td><td{css}>{r["deltaPct"]:+.2f} %</td><td>{a["calls"]} → {b["calls"]}</td><td>{a["triangles"]} → {b["triangles"]}</td></tr>')
exceptions=[r for r in perf['rows'] if r['profile']=='balanced' and r['deltaPct']>5]
parts.append(f'</table></div><p class="note">Objectif ≤5 % Équilibré : {len(exceptions)}/8 scènes le dépassent. '+('Réserve ouverte : '+', '.join(esc(r['scene']) for r in exceptions)+'.' if exceptions else 'Aucun dépassement observé dans cette passe logicielle ; validation matérielle toujours ouverte.')+'</p><h3>Coût actif du bateau (rendu isolé)</h3><div class="table"><table><tr><th>Profil</th><th>Sans → actif, médiane</th><th>Appels / triangles supplémentaires</th></tr>')
for r in active['rows']:
    a,b=r['off'],r['on'];parts.append(f'<tr><td>{r["profile"]}</td><td>{a["medianMs"]:.1f} → {b["medianMs"]:.1f} ms</td><td>+{b["calls"]-a["calls"]} / +{b["triangles"]-a["triangles"]}</td></tr>')
parts.append(f'</table></div><p>369 tests réussis ; M24 figé : 360. TypeScript/Vite réussis, avertissement historique de bundle &gt;500 ko conservé. {preserve["protectedUnchanged"]} fichiers protégés identiques. Données géographiques, graphe, restrictions et workflows de production préservés.</p><p><a href="performance.json">Mesures et échantillons bruts</a> · <a href="active-performance.json">Coût actif</a> · <a href="preservation.json">Empreintes des sources</a> · <a href="audio.json">Audio</a> · <a href="mobile.json">Tactile</a> · <a href="compiled-mobile.json">Bundle mobile</a> · <a href="regression.json">Collisions</a> · <a href="loading.json">Chargement et taille des bundles</a> · <a href="tests.txt">Tests</a> · <a href="build.txt">Build</a></p></section>')
report=Path('docs/mission-25.md').read_text();matrix=report.split('## Matrice d’acceptation')[1];rows=[r for r in matrix.splitlines() if r.startswith('|')][2:]
parts.append('<section id="acceptation"><h2>Matrice d’acceptation</h2><div class="table"><table><tr><th>Exigence</th><th>État</th><th>Preuve / réserve</th></tr>')
for row in rows: parts.append('<tr>'+''.join('<td>'+esc(v.strip().replace('**',''))+'</td>' for v in row.strip('|').split('|'))+'</tr>')
parts.append('</table></div><p>Budget externe supplémentaire : 0 €. Aucun déploiement, fusion ou changement de production. Les éléments incomplets sont des chantiers ouverts.</p></section></main><script>document.querySelectorAll("[data-speed]").forEach(b=>b.onclick=()=>document.querySelectorAll("video").forEach(v=>v.playbackRate=+b.dataset.speed));document.querySelector("#pause").onclick=()=>document.querySelectorAll("video").forEach(v=>v.pause());</script></html>')
(out/'index.html').write_text(''.join(parts))
print('Gallery generated:',len(list(out.glob('*.webm'))),'native films')
